            }
            else {
                rev = rs.getRevisionByName(proj.getId(), revName); // check NotFound first
            }
            StoredWorkflowDefinition def = rs.getWorkflowDefinitionByName(rev.getId(), wfName); // check NotFound first

            ac.checkGetWorkflow( // AccessControl
                    WorkflowTarget.of(getSiteId(), def.getName(), proj.getName()),
                    getAuthenticatedUser());

            return RestModels.workflowDefinition(proj, rev, def);
        }, ResourceNotFoundException.class, AccessControlException.class);
    }

    @DigdagTimed(category="api", appendMethodName = true)
    @GET
    @Path("/api/workflows")
    @ApiOperation("List workflows")
    public RestWorkflowDefinitionCollection getWorkflowDefinitions(
            @ApiParam(value="pagination. return workflows which id are greater than last_id with order 'asc', which id are less than the last_id with order 'desc'", required=false)
            @QueryParam("last_id") Long lastId,
            @ApiParam(value="number of workflows to return", required=false)
            @QueryParam("count") Integer count,
            @ApiParam(value="Sort order. 'asc' or 'desc'", defaultValue = "asc", required=false)
            @DefaultValue("asc") @QueryParam("order") String orderDirection,
            @ApiParam(value="name pattern to be partially matched", required=false)
            @QueryParam("name_pattern") String namePattern,
            @ApiParam(value="name pattern to be partially matched", required=false)
            @DefaultValue("false") @QueryParam("search_project_name") Boolean searchProjectName
    )
            throws ResourceNotFoundException, AccessControlException
    {
        final SiteTarget siteTarget = SiteTarget.of(getSiteId());
        ac.checkListWorkflowsOfSite(siteTarget, getAuthenticatedUser());  // AccessControl
        return tm.<RestWorkflowDefinitionCollection, ResourceNotFoundException, AccessControlException>begin(() -> {
            List<StoredWorkflowDefinitionWithProject> defs =
                    rm.getProjectStore(getSiteId())
                            .getLatestActiveWorkflowDefinitions(
                                    Optional.fromNullable(count).or(100),
                                    Optional.fromNullable(lastId), // check NotFound first
                                    orderAscending(orderDirection),
                                    Optional.fromNullable(namePattern),
                                    searchProjectName,
                                    ac.getListWorkflowsFilterOfSite(
                                            SiteTarget.of(getSiteId()),
                                            getAuthenticatedUser()));

            return RestModels.workflowDefinitionCollection(defs);
        }, ResourceNotFoundException.class, AccessControlException.class);
    }

    private boolean orderAscending(String orderDirection)
    {
        if (orderDirection == null || orderDirection.equals("asc")) {
            return true;
        }
        else if (orderDirection.equals("desc")) {
            return false;
        }
        else {
            throw new IllegalArgumentException("parameter 'order' must be either 'asc' or 'desc'");
        }
    }

    @DigdagTimed(category = "api", value = "getWorkflowDefinitionById")
    @GET
    @Path("/api/workflows/{id}")
    @ApiOperation("Get a workflow")
    public RestWorkflowDefinition getWorkflowDefinition(
            @ApiParam(value="workflow id", required=true)
            @PathParam("id") long id)
            throws ResourceNotFoundException, AccessControlException
    {
        return tm.<RestWorkflowDefinition, ResourceNotFoundException, AccessControlException>begin(() -> {
            StoredWorkflowDefinitionWithProject def =
                    rm.getProjectStore(getSiteId())
                            .getWorkflowDefinitionById(id); // check NotFound first

            ac.checkGetWorkflow( // AccessControl
                    WorkflowTarget.of(getSiteId(), def.getName(), def.getProject().getName()),
                    getAuthenticatedUser());

            return RestModels.workflowDefinition(def);
        }, ResourceNotFoundException.class, AccessControlException.class);
    }

    @DigdagTimed(category = "api", appendMethodName = true)
    @GET
    @Path("/api/workflows/{id}/truncated_session_time")
    @ApiOperation("Get truncated local time based on the time zone of a workflow")
    public RestWorkflowSessionTime getWorkflowDefinition(
            @ApiParam(value="workflow id", required=true)
            @PathParam("id") long id,
            @ApiParam(value="session time to be truncated", required=true)
            @QueryParam("session_time") LocalTimeOrInstant localTime,
            @ApiParam(value="truncation mode - second, minute, hour, day, schedule, or next_schedule", required=false)
            @QueryParam("mode") SessionTimeTruncate mode)
            throws ResourceNotFoundException, AccessControlException
    {
        return tm.<RestWorkflowSessionTime, ResourceNotFoundException, AccessControlException>begin(() -> {
            Preconditions.checkArgument(localTime != null, "session_time= is required");

            StoredWorkflowDefinitionWithProject def =
                    rm.getProjectStore(getSiteId())
                            .getWorkflowDefinitionById(id); // check NotFound first

            ac.checkGetWorkflow( // AccessControl
                    WorkflowTarget.of(getSiteId(), def.getName(), def.getProject().getName()),
                    getAuthenticatedUser());

            ZoneId timeZone = def.getTimeZone();

            Instant truncated;
            if (mode != null) {
                truncated = truncateSessionTime(
                        localTime.toInstant(timeZone),
                        timeZone, () -> srm.tryGetScheduler(def), mode);
            }
            else {
                truncated = localTime.toInstant(timeZone);
            }

            return RestModels.workflowSessionTime(
                    def, truncated, timeZone);
        }, ResourceNotFoundException.class, AccessControlException.class);
    }

    private Instant truncateSessionTime(
            Instant sessionTime,
            ZoneId timeZone,
            Supplier<Optional<Scheduler>> schedulerSupplier,
            SessionTimeTruncate mode)
    {
        switch (mode) {
        case HOUR:
            return ZonedDateTime.ofInstant(sessionTime, timeZone)
                .truncatedTo(ChronoUnit.HOURS)
                .toInstant();
        case DAY:
            return ZonedDateTime.ofInstant(sessionTime, timeZone)
                .truncatedTo(ChronoUnit.DAYS)
                .toInstant();
        default:
            {
                Optional<Scheduler> scheduler = schedulerSupplier.get();
                if (!scheduler.isPresent()) {
                    throw new IllegalArgumentException("session_time_truncate=" + mode + " is set but schedule is not set to this workflow");
                }
                switch (mode) {
                case SCHEDULE:
                    return scheduler.get().getFirstScheduleTime(sessionTime).getTime();
                case NEXT_SCHEDULE:
                    return scheduler.get().nextScheduleTime(sessionTime).getTime();
                default:
                    throw new IllegalArgumentException();
                }
            }
        }
    }
}

public class ServerBootstrap
    implements io.digdag.guice.rs.server.ServerBootstrap
{
    private static final Logger logger = LoggerFactory.getLogger(ServerBootstrap.class);

    protected final Version version;
    protected final ServerConfig serverConfig;
    private final PluginSet systemPlugins;

    public ServerBootstrap(Version version, ServerConfig serverConfig, PluginSet systemPlugins)
    {
        this.version = version;
        this.serverConfig = serverConfig;
        this.systemPlugins = systemPlugins;
    }

    public ServerBootstrap(Version version, ServerConfig serverConfig)
    {
        this(version, serverConfig, PluginSet.empty());
    }

    @Override
    public Bootstrap bootstrap()
    {
        return digdagBootstrap()
                .build();
    }

    protected DigdagEmbed.Bootstrap digdagBootstrap()
    {
        return new DigdagEmbed.Bootstrap()
            .setEnvironment(serverConfig.getEnvironment())
            .setSystemConfig(serverConfig.getSystemConfig())
            .setSystemPlugins(systemPlugins)
            .overrideModulesWith((binder) -> {
                binder.bind(WorkspaceManager.class).to(ExtractArchiveWorkspaceManager.class).in(Scopes.SINGLETON);
                binder.bind(Version.class).toInstance(version);
            })
            .addModules((binder) -> {
                binder.bind(ServerRuntimeInfoWriter.class).asEagerSingleton();
                binder.bind(ServerConfig.class).toInstance(serverConfig);
                binder.bind(WorkflowExecutorLoop.class).asEagerSingleton();
                binder.bind(WorkflowExecutionTimeoutEnforcer.class).asEagerSingleton();
                binder.bind(ClientVersionChecker.class).toProvider(ClientVersionCheckerProvider.class);

                binder.bind(ErrorReporter.class).to(JmxErrorReporter.class).in(Scopes.SINGLETON);
                newExporter(binder).export(ErrorReporter.class).withGeneratedName();
            })
            .addModules(new ServerModule(serverConfig))
            .overrideModulesWith(new DigdagMetricsModule(new DigdagMetricsConfig(serverConfig.getSystemConfig().toConfig(ServerConfig.configFactory()))))
        ;
    }

    public static GuiceRsServerControl start(ServerBootstrap bootstrap)
        throws ServletException
    {
        UndertowServerControl control = UndertowServer.start(bootstrap.serverConfig, bootstrap);

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            control.stop();
            control.destroy();
            logger.info("Shutdown completed");
        }, "shutdown"));

        return control;
    }

    private static class ClientVersionCheckerProvider
            implements Provider<ClientVersionChecker>
    {
        private final Config systemConfig;

        @Inject
        public ClientVersionCheckerProvider(Config systemConfig)
        {
            this.systemConfig = systemConfig;
        }

        @Override
        public ClientVersionChecker get()
        {
            return ClientVersionChecker.fromSystemConfig(systemConfig);
        }
    }
}

public class DigdagMetricsConfig
{
    private static Logger logger = LoggerFactory.getLogger(DigdagMetricsConfig.class);
    private Map<String, MonitorSystemConfig> monitorSystems = new HashMap<>();

    public Optional<MonitorSystemConfig> getMonitorSystemConfig(String key)
    {
        return monitorSystems.containsKey(key) ? Optional.of(monitorSystems.get(key)) : Optional.absent();
    }

    public DigdagMetricsConfig(Config config)
    {
        // fetch enabled monitor system metrics.enable = jmx,...
        List<String> keys = config
                .getOptional("metrics.enable", String.class)
                .transform((s) ->
                        Arrays.asList(s.split(","))
                                .stream()
                                .map((x) -> x.trim())
                                .distinct()
                                .collect(Collectors.toList())
                ).or(Arrays.asList());
        // load each config
        keys.stream().forEach((k) -> monitorSystems.put(k, loadMonitorSystemConfig(k, config)));
    }

    /**
     * Override for extend
     * @param key
     * @param config
     * @return
     */
    protected MonitorSystemConfig loadMonitorSystemConfig(String key, Config config)
    {
        switch (key) {
            case "jmx":
                return getJmxMonitorSystemConfig(config);
            case "fluency":
                return getFluencyMonitorSystemConfig(config);
            default:
                throw new ConfigException("Unsupported digdag-metrics monitor system:" + key);
        }
    }

    JmxMonitorSystemConfig getJmxMonitorSystemConfig(Config config)
    {
        return JmxMonitorSystemConfig.load(config);
    }

    FluencyMonitorSystemConfig getFluencyMonitorSystemConfig(Config config)
    {
        return FluencyMonitorSystemConfig.load(config);
    }
}

public class BasicAuthenticator
    implements Authenticator
{
    private final ConfigFactory cf;
    private final String username;
    private final String password;
    private final boolean admin;

    public BasicAuthenticator(ConfigFactory cf,
            String username, String password, boolean admin)
    {
        this.cf = cf;
        this.username = username;
        this.password = password;
        this.admin = admin;
    }

    @Override
    public Authenticator.Result authenticate(ContainerRequestContext requestContext)
    {
        String authHeader = requestContext.getHeaderString(AUTHORIZATION);
        if (authHeader == null) {
            return Result.reject("Missing Authorization header");
        }

        String[] parsedHeader = BasicAuthHelper.parseHeader(authHeader);

        if (parsedHeader[0].equals(username) && parsedHeader[1].equals(password)) {
            AuthenticatedUser user = AuthenticatedUser.builder()
                .siteId(0)
                .userInfo(cf.create())
                .userContext(cf.create())
                .isAdmin(admin)
                .build();
            return Result.accept(user);
        }
        else {
            return Result.reject("unauthorized");
        }
    }
}

public class NoAuthenticator
    implements Authenticator
{
    private static final Logger logger = LoggerFactory.getLogger(NoAuthenticator.class);

    private final ConfigFactory cf;

    public NoAuthenticator(ConfigFactory cf)
    {
        logger.debug("No authentication is configured. No authentication is required to call REST API.");
        this.cf = cf;
    }

    @Override
    public Authenticator.Result authenticate(ContainerRequestContext requestContext)
    {
        AuthenticatedUser user = AuthenticatedUser.builder()
            .siteId(0)
            .userInfo(cf.create())
            .userContext(cf.create())
            .build();
        return Result.accept(user);
    }
}

