public class ServerRuntimeInfoWriter
{
    private static final Logger logger = LoggerFactory.getLogger(ServerRuntimeInfoWriter.class);

    private final Optional<String> serverInfoPath;
    private final GuiceRsServerControl serverControl;

    @Inject
    public ServerRuntimeInfoWriter(ServerConfig serverConfig, GuiceRsServerControl serverControl)
    {
        this.serverInfoPath = serverConfig.getServerRuntimeInfoPath();
        this.serverControl = serverControl;
    }

    @PostStart
    public void postStart()
    {
        if (serverInfoPath.isPresent()) {
            List<ServerRuntimeInfo.Address> apiAddresses = serverControl.getRuntimeInfo().getListenAddresses()
                .stream()
                .filter(a -> a.getName().equals(ServerConfig.API_ADDRESS))
                .map(a -> a.getSocketAddress())
                .map(sa -> ServerRuntimeInfo.Address.of(sa.getHostString(), sa.getPort()))
                .collect(Collectors.toList());
            List<ServerRuntimeInfo.Address> adminAddresses = serverControl.getRuntimeInfo().getListenAddresses()
                .stream()
                .filter(a -> a.getName().equals(ServerConfig.ADMIN_ADDRESS))
                .map(a -> a.getSocketAddress())
                .map(sa -> ServerRuntimeInfo.Address.of(sa.getHostString(), sa.getPort()))
                .collect(Collectors.toList());

            ServerRuntimeInfo serverRuntimeInfo = ServerRuntimeInfo.builder()
                .localAddresses(apiAddresses)
                .localAdminAddresses(adminAddresses)
                .build();

            ObjectMapper mapper = new ObjectMapper();
            try {
                Files.write(Paths.get(serverInfoPath.get()), mapper.writeValueAsBytes(serverRuntimeInfo));
            }
            catch (IOException e) {
                logger.warn("Failed to write server runtime info", e);
            }
        }
    }
}

public class WorkflowExecutionTimeoutEnforcer
{
    private static final Logger logger = LoggerFactory.getLogger(WorkflowExecutionTimeoutEnforcer.class);

    private static final Duration DEFAULT_ATTEMPT_TTL = Duration.ofDays(7);
    private static final Duration DEFAULT_TASK_TTL = Duration.ofDays(1);
    private static final Duration DEFAULT_REAPING_INTERVAL = Duration.ofSeconds(5);

    // This is similar to TaskStateCode.notDoneStates() but BLOCKED, PLANNED, and READY are excluded.
    // BLOCKED and PLANNED are excluded because there're other running tasks that should be enforced instead.
    // READY is excluded the workflow itself is working correctly and number of threads is insufficient.
    private static final TaskStateCode[] TASK_TTL_ENFORCED_STATE_CODES = new TaskStateCode[] {
        TaskStateCode.RETRY_WAITING,
        TaskStateCode.GROUP_RETRY_WAITING,
        TaskStateCode.RUNNING,
    };

    private final ScheduledExecutorService scheduledExecutorService;
    private final SessionStoreManager ssm;
    private final Notifier notifier;
    private final ProjectStoreManager psm;
    private final TransactionManager tm;

    private final Duration attemptTTL;
    private final Duration reapingInterval;
    private final Duration taskTTL;

    @Inject
    public WorkflowExecutionTimeoutEnforcer(
            ServerConfig serverConfig,
            SessionStoreManager ssm,
            TransactionManager tm,
            Config systemConfig,
            Notifier notifier,
            ProjectStoreManager psm)
    {
        this.attemptTTL = systemConfig.getOptional("executor.attempt_ttl", DurationParam.class)
                .transform(DurationParam::getDuration)
                .or(DEFAULT_ATTEMPT_TTL);

        this.taskTTL = systemConfig.getOptional("executor.task_ttl", DurationParam.class)
                .transform(DurationParam::getDuration)
                .or(DEFAULT_TASK_TTL);

        this.reapingInterval = systemConfig.getOptional("executor.ttl_reaping_interval", DurationParam.class)
                .transform(DurationParam::getDuration)
                .or(DEFAULT_REAPING_INTERVAL);

        this.ssm = ssm;
        this.notifier = notifier;
        this.psm = psm;
        this.tm = tm;

        if (serverConfig.getExecutorEnabled()) {
            this.scheduledExecutorService = Executors.newSingleThreadScheduledExecutor(new ThreadFactoryBuilder()
                    .setDaemon(true)
                    .setNameFormat("attempt-timeout-enforcer-%d")
                    .build());
        }
        else {
            this.scheduledExecutorService = null;
        }
    }

    private void run()
    {
        try {
            enforceAttemptTTLs();
        }
        catch (Throwable t) {
            logger.error(
                    LogMarkers.UNEXPECTED_SERVER_ERROR,
                    "Uncaught exception when enforcing attempt TTLs. Ignoring. Loop will be retried.", t);
        }

        try {
            enforceTaskTTLs();
        }
        catch (Throwable t) {
            logger.error(
                    LogMarkers.UNEXPECTED_SERVER_ERROR,
                    "Uncaught exception when enforcing task TTLs. Ignoring. Loop will be retried.", t);
        }
    }

    private void enforceAttemptTTLs()
    {
        List<StoredSessionAttempt> expiredAttempts = tm.begin(() -> {
            Instant creationDeadline = ssm.getStoreTime().minus(attemptTTL);
            return ssm.findActiveAttemptsCreatedBefore(creationDeadline, (long) 0, 100);
        });

        for (StoredSessionAttempt attempt : expiredAttempts) {
            try {
                boolean canceled = tm.begin(() -> {
                    AttemptStateFlags stateFlags;
                    try {
                        stateFlags = ssm.getAttemptStateFlags(attempt.getId());
                    }
                    catch (ResourceNotFoundException e) {
                        logger.debug("Session Attempt not found, ignoring: {}", attempt, e);
                        return null;
                    }

                    if (stateFlags.isCancelRequested()) {
                        logger.debug("Session Attempt already canceled, ignoring: {}", attempt);
                        return null;
                    }

                    logger.info("Session Attempt timed out, canceling: {}", attempt);
                    return ssm.requestCancelAttempt(attempt.getId());
                });

                if (canceled) {
                    sendTimeoutNotification("Workflow execution timeout", attempt.getId());
                }
            }
            catch (Throwable t) {
                logger.error(
                        LogMarkers.UNEXPECTED_SERVER_ERROR,
                        "Uncaught exception when enforcing attempt TTLs of attempt {}. Ignoring. Loop continues.", attempt.getId(), t);
            }
        }
    }

    private void enforceTaskTTLs()
    {
        List<TaskAttemptSummary> expiredTasks = tm.begin(() -> {
            Instant startDeadline = ssm.getStoreTime().minus(taskTTL);
            return ssm.findTasksStartedBeforeWithState(TASK_TTL_ENFORCED_STATE_CODES, startDeadline, (long) 0, 100);
        });

        Map<Long, List<TaskAttemptSummary>> attempts = expiredTasks.stream()
                .collect(groupingBy(TaskAttemptSummary::getAttemptId));

        for (Map.Entry<Long, List<TaskAttemptSummary>> entry : attempts.entrySet()) {
            long attemptId = entry.getKey();
            try {
                boolean canceled = tm.begin(() -> {
                    logger.info("Task(s) timed out, canceling Session Attempt: {}, tasks={}", attemptId, entry.getValue());
                    return ssm.requestCancelAttempt(attemptId);
                });

                if (canceled) {
                    String taskIds = entry.getValue().stream().mapToLong(TaskAttemptSummary::getId).mapToObj(Long::toString).collect(joining(","));
                    sendTimeoutNotification("Task execution timeout: " + taskIds, attemptId);
                }
            }
            catch (Throwable t) {
                logger.error(
                        LogMarkers.UNEXPECTED_SERVER_ERROR,
                        "Uncaught exception when enforcing task TTLs of attempt {}. Ignoring. Loop continues.", entry.getKey(), t);
            }
        }
    }

    private void sendTimeoutNotification(String message, long attemptId)
    {
        StoredSessionAttemptWithSession attempt;
        try {
            attempt = tm.begin(() -> ssm.getAttemptWithSessionById(attemptId), ResourceNotFoundException.class);
        }
        catch (ResourceNotFoundException e) {
            logger.error("Session attempt not found, ignoring: {}", attemptId);
            return;
        }

        int projectId = attempt.getSession().getProjectId();
        StoredProject project;
        try {
            project = tm.begin(() -> psm.getProjectByIdInternal(projectId), ResourceNotFoundException.class);
        }
        catch (ResourceNotFoundException e) {
            logger.error("Project not found, ignoring: {}", attemptId);
            return;
        }

        Optional<Long> wfId = attempt.getWorkflowDefinitionId();

        Optional<StoredWorkflowDefinitionWithProject> workflow = Optional.absent();
        if (wfId.isPresent()) {
            try {
                workflow = Optional.of(tm.begin(() -> psm.getWorkflowDetailsById(wfId.get()), ResourceNotFoundException.class));
            }
            catch (ResourceNotFoundException e) {
                workflow = Optional.absent();
            }
        }

        Notification notification = Notification.builder(Instant.now(), message)
                .attemptId(attempt.getId())
                .projectId(projectId)
                .projectName(project.getName())
                .revision(workflow.transform(wf -> wf.getRevisionName()))
                .sessionId(attempt.getSessionId())
                .siteId(attempt.getSiteId())
                .workflowName(workflow.transform(wf -> wf.getName()))
                .workflowDefinitionId(wfId)
                .build();

        try {
            // Assuming this method creates a new database transaction if needed. So this method call
            // is in outside of tm.begin block.
            notifier.sendNotification(notification);
        }
        catch (NotificationException e) {
            logger.error("Failed to send execution timeout notification for attempt: {}", attemptId, e);
        }
    }

    @PostConstruct
    public void start()
    {
        if (scheduledExecutorService != null) {
            scheduledExecutorService.scheduleAtFixedRate(this::run, reapingInterval.toNanos(), reapingInterval.toNanos(), NANOSECONDS);
        }
    }

    @PreDestroy
    public void shutdown()
            throws InterruptedException
    {
        if (scheduledExecutorService != null) {
            scheduledExecutorService.shutdownNow();
        }
    }
}

public class WorkflowExecutorLoop
        implements BackgroundExecutor
{
    private static final Logger logger = LoggerFactory.getLogger(WorkflowExecutorLoop.class);

    private final Supplier<Thread> threadFactory;
    private final WorkflowExecutor workflowExecutor;

    private volatile Thread thread = null;
    private volatile boolean stop = false;

    @Inject(optional = true)
    private ErrorReporter errorReporter = ErrorReporter.empty();

    @Inject
    private DigdagMetrics metrics;

    @Inject
    public WorkflowExecutorLoop(
            ServerConfig serverConfig,
            WorkflowExecutor workflowExecutor)
    {
        if (serverConfig.getExecutorEnabled()) {
            this.threadFactory = () -> new ThreadFactoryBuilder()
                .setDaemon(true)
                .setNameFormat("workflow-executor-%d")
                .build()
                .newThread(this::run);
        }
        else {
            this.threadFactory = null;
        }
        this.workflowExecutor = workflowExecutor;
    }

    private void run()
    {
        while (!stop) {
            try {
                workflowExecutor.runWhile(() -> !stop);
            }
            catch (Throwable t) {
                logger.error(
                        LogMarkers.UNEXPECTED_SERVER_ERROR,
                        "Uncaught error during executing workflow state machine. Ignoring. Loop will be retried.", t);
                errorReporter.reportUncaughtError(t);
                metrics.increment(Category.EXECUTOR, "uncaughtErrors");
                try {
                    // sleep before retrying
                    Thread.sleep(1000);
                }
                catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    @PostConstruct
    public synchronized void start()
    {
        if (threadFactory != null && thread == null) {
            Thread thread = threadFactory.get();
            thread.start();
            this.thread = thread;
        }
    }

    @PreDestroy
    public synchronized void shutdown()
        throws InterruptedException
    {
        startShutdown();

        if (thread != null) {
            thread.join(100);
            if (thread.isAlive()) {
                logger.info("Waiting for completion of workflow executor loop...");
                do {
                    workflowExecutor.noticeRunWhileConditionChange();
                    thread.join(1000);
                } while (thread.isAlive());
            }
            thread = null;
        }
    }

    @Override
    public void eagerShutdown()
            throws InterruptedException
    {
        startShutdown();
    }

    private void startShutdown()
    {
        if (!stop) {
            stop = true;
            logger.info("Shutting down workflow executor loop");

            // noticeRunWhileConditionChange is not 100% accurate because
            // WorkflowExecutor doesn't lock stop flag before check. But
            // it will be repeated in shutdown() method later
            workflowExecutor.noticeRunWhileConditionChange();
        }
    }
}

public class DigdagMetricsModule
        extends AbstractModule
{
    // To customize easily
    protected final DigdagMetricsConfig metricsConfig;

    private static final Logger logger = LoggerFactory.getLogger(DigdagMetricsModule.class);

    public DigdagMetricsModule(DigdagMetricsConfig metricsConfig)
    {
        this.metricsConfig = metricsConfig;
    }

    @Override
    public void configure()
    {
        configureMeterRegistry();
        binder().bind(DigdagMetrics.class).to(StdDigdagMetrics.class);
        configureInterceptor();
    }

    /**
     *  Configure MeterRegistry.
     *  As default, JmxMeterRegistry is used.
     *  If want to change MeterRegistry, override this method.
     */
    public void configureMeterRegistry()
    {
        bindMeterRegistry(Category.DEFAULT);
        bindMeterRegistry(Category.AGENT);
        bindMeterRegistry(Category.API);
        bindMeterRegistry(Category.DB);
        bindMeterRegistry(Category.EXECUTOR);
    }

    protected void bindMeterRegistry(Category category)
    {
        binder().bind(MeterRegistry.class)
                .annotatedWith(Names.named(category.getString()))
                .toInstance(createCompositeMeterRegistry(category));
    }

    /**
     * Override this method is easy way to add additional MeterRegistry
     * @param category
     * @return
     */
    protected CompositeMeterRegistry createCompositeMeterRegistry(Category category)
    {
        CompositeMeterRegistry registry = new CompositeMeterRegistry();

        if (isEnableCategory("jmx", category)) {
            registry.add(createJmxMeterRegistry(category));
        }
        if (isEnableCategory("fluency", category)) {
            registry.add(createFluencyMeterRegistry(category));
        }

        return registry;
    }

    protected boolean isEnableCategory(String key, Category category)
    {
        return metricsConfig.getMonitorSystemConfig(key).transform( (p) -> p.getCategoryEnable(category)).or(false);
    }


    private final Map<Category,String> categoryToJMXdomain = ImmutableMap.of(
            Category.DEFAULT, "io.digdag",
            Category.AGENT, "io.digdag.agent",
            Category.API, "io.digdag.api",
            Category.DB, "io.digdag.db",
            Category.EXECUTOR, "io.digdag.executor"
    );

    // To customize easily
    protected JmxMeterRegistry createJmxMeterRegistry(Category category)
    {
        return new JmxMeterRegistry(createJmxConfig(categoryToJMXdomain.get(category)), Clock.SYSTEM);
    }

    private JmxConfig createJmxConfig(String domain)
    {
        return new JmxConfig() {
            @Override
            public String get(String key) {
                return null;
            }
            @Override
            public String domain() {
                return domain;
            }
        };
    }

    @VisibleForTesting
    public FluencyMeterRegistry createFluencyMeterRegistry(Category category)
    {
        FluencyMonitorSystemConfig fconfig = (FluencyMonitorSystemConfig)metricsConfig
                .getMonitorSystemConfig("fluency")
                .or(() -> {throw new ConfigException("fluency is disabled");});
        Fluency fluency = FluencyMonitorSystemConfig.createFluency(fconfig);
        FluencyRegistryConfig regConfig = FluencyRegistryConfig.apply(fconfig.getTag(), "digdag", Duration.ofSeconds(fconfig.getStep()), false);
        return FluencyMeterRegistry.apply(regConfig, HierarchicalNameMapper.DEFAULT, Clock.SYSTEM, fluency);
    }


    // Set interceptor for @DigdagTimed annotation
    public void configureInterceptor()
    {
        DigdagTimedMethodInterceptor interceptor = new DigdagTimedMethodInterceptor();
        requestInjection(interceptor);
        binder().bindInterceptor(Matchers.any(), Matchers.annotatedWith(DigdagTimed.class), interceptor);
    }
}

public interface MonitorSystemConfig
{
    boolean getMonitorSystemEnable();

    boolean getCategoryDefaultEnable();

    boolean getCategoryAgentEnable();

    boolean getCategoryApiEnable();

    boolean getCategoryDbEnable();

    boolean getCategoryExecutorEnable();

    default boolean enable(Category category)
    {
        return getMonitorSystemEnable() && getCategoryEnable(category);
    }

    default boolean getCategoryEnable(Category category)
    {
        switch (category) {
            case DEFAULT:
                return getCategoryDefaultEnable();
            case AGENT:
                return getCategoryAgentEnable();
            case API:
                return getCategoryApiEnable();
            case DB:
                return getCategoryDbEnable();
            case EXECUTOR:
                return getCategoryExecutorEnable();
            default:
                return false;
        }
    }

    static Map<Category, Boolean> getEnabledCategories(Optional<String> config)
    {
        List<Category> ALL = Arrays.asList(Category.class.getEnumConstants());
        Map<Category, Boolean> map = new HashMap<>();
        for (Category c: ALL) {
            map.put(c, false);
        }
        List<Category> enables = config
                .transform( (s) ->
                        Arrays.asList(s.split(","))
                            .stream()
                            .map( (x) -> x.trim())
                            .flatMap( (x) -> {
                                    List<Category> ret;
                                    if (x.compareToIgnoreCase("all") == 0) {
                                        ret = ALL;
                                    }
                                    else {
                                        ret = Arrays.asList(Category.fromString(x));
                                    }
                                    return ret.stream();
                                })
                                .distinct()
                                .collect(Collectors.toList())
                )
                .or(ALL);
        for (Category c: enables) {
            map.put(c, true);
        }
        return map;
    }

}

