public abstract class AuthenticatedResource
{
    @Context
    protected HttpServletRequest request;

    protected int getSiteId()
    {
        // siteId is set by JwtAuthInterceptor
        // TODO validate before causing NPE. Improve guice-rs to call @PostConstruct
        return getAuthenticatedUser().getSiteId();
    }

    protected Config getUserInfo()
    {
        return getAuthenticatedUser().getUserInfo();
    }

    protected AuthenticatedUser getAuthenticatedUser()
    {
        return (AuthenticatedUser) request.getAttribute("authenticatedUser");
    }

    /**
     * Get request context default secrets.
     */
    @SuppressWarnings("unchecked")
    protected Supplier<Map<String, String>> getSecrets()
    {
        return (Supplier<Map<String, String>>) request.getAttribute("secrets");
    }
}

public class DuplicateInputStream
        extends FilterInputStream
{
    private final OutputStream out;
    private byte[] tempBuffer;

    public DuplicateInputStream(InputStream in, OutputStream out)
    {
        super(in);
        this.out = out;
    }

    private void ensureTempBuffer()
    {
        if (tempBuffer == null) {
            tempBuffer = new byte[32 * 1024];
        }
    }

    @Override
    public int read() throws IOException
    {
        int c = in.read();
        if (c >= 0) {
            out.write(c);
        }
        return c;
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException
    {
        int n = in.read(b, off, len);
        if (n >= 0) {
            out.write(b, off, n);
        }
        return n;
    }

    @Override
    public int read(byte[] b) throws IOException
    {
        return read(b, 0, b.length);
    }

    @Override
    public long skip(long n) throws IOException
    {
        ensureTempBuffer();
        return read(tempBuffer, 0, (int) Math.min(n, tempBuffer.length));
    }

    @Override
    public void close() throws IOException
    {
        ensureTempBuffer();
        while (read(tempBuffer) >= 0);
        in.close();
    }

    public void abort() throws IOException
    {
        in.close();
    }

    @Override
    public int available() throws IOException
    {
        return in.available();
    }

    @Override
    public boolean markSupported()
    {
        return false;
    }

    @Override
    public void mark(int readlimit)
    { }

    @Override
    public void reset() throws IOException
    {
        throw new IOException("mark/reset not supported");
    }
}

public class QueryParamValidator
{
    public static int validatePageSize(Optional<Integer> pageSize, int maxPageSize, int defaultPageSize)
            throws IllegalArgumentException
    {
        if (!pageSize.isPresent()) { return defaultPageSize; }

        int pageSizeValue = pageSize.get().intValue();
        if (pageSizeValue > maxPageSize) {
            String message = "Your specified page_size is " + pageSize + ", " +
                    "but it is larger than MAX_PAGE_SIZE: " + maxPageSize + ". " +
                    "You must specify page_size with a number which is smaller than " + maxPageSize + ".";

            // This error results 400 response
            throw new IllegalArgumentException(message);
        }
        else {
            return pageSizeValue;
        }
    }
}

